INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_004_v1_credibility@6534901b983d2bb1', 'signal-repo-597ab80a4c0e-1047', 'repo-597ab80a4c0e', 'discussion_inconclusive', '{"signal_id": "signal-repo-597ab80a4c0e-1047", "repository_id": "repo-597ab80a4c0e", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/state-spaces/mamba/issues/1047", "source_title": "[Bug] Mamba2 RMSNormGated uses the global ngroups for group_size under tensor parallelism", "source_excerpt": "[Bug] Mamba2 RMSNormGated uses the global ngroups for group_size under tensor parallelism\n### Summary\n\nWith tensor parallelism, `Mamba2` builds its gated RMSNorm with a group size that is `world_size` times too small ([mamba2.py#L144-L145](https://github.com/state-spaces/mamba/blob/e9594ce1c732d97440f0332fdc43170a2294dbfa/mamba_ssm/modules/mamba2.py#L144-L145)):\n\n```python\nself.norm = RMSNormGated", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:11.575316Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": []}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_004_v1_credibility@6534901b983d2bb1', 'signal-repo-597ab80a4c0e-1024', 'repo-597ab80a4c0e', 'discussion_inconclusive', '{"signal_id": "signal-repo-597ab80a4c0e-1024", "repository_id": "repo-597ab80a4c0e", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/state-spaces/mamba/issues/1024", "source_title": "Mamba3 step() is non-deterministic and does not match forward()", "source_excerpt": "Mamba3 step() is non-deterministic and does not match forward()\n## Question\n\nI have noticed there is an output difference between calling `step()` and `forward()`.\n\nWhen using the same model and feeding in the exact same input sequence, invoking `Mamba3.forward()` directly versus running multiple `Mamba3.step()` calls in a loop yields outputs that diverge noticeably, with a maximum difference valu", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:11.577335Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/state-spaces/mamba/issues/1024#issuecomment-5717569384", "excerpt": "Root cause identified: OOB writes when headdim < tile_D (hardcoded 64)\nThe reporter''s config uses headdim=16, but step() hardcodes tile_D=64 (mamba3.py L402/L425). The kernel launches grid = ceil_div(mState.shape[2]=16, 64) = 1 (mamba3_step_fn.py L221) while each block reads or writes a 64-wide tile of state and output with no bounds checking (# Load State, not doing any bound check for now, L384)", "login": "imao81"}, {"source_url": "https://github.com/state-spaces/mamba/issues/1024#issuecomment-5727940101", "excerpt": "Fix submitted in #1046: shape-based routing — SISO configs with headdim % 64 != 0 fall back to the existing Triton step kernel (bitwise-deterministic, no param corruption, step-vs-forward ~6.5e-3); CuTe path bit-exact unchanged; unsafe configs raise NotImplementedError.", "login": "imao81"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_004_v1_credibility@6534901b983d2bb1', 'signal-repo-597ab80a4c0e-1022', 'repo-597ab80a4c0e', 'discussion_inconclusive', '{"signal_id": "signal-repo-597ab80a4c0e-1022", "repository_id": "repo-597ab80a4c0e", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/state-spaces/mamba/issues/1022#issuecomment-5431600555", "source_title": "Mamba-3 incremental decode broken: `step()` receives `(B, 1, D)` but `_preprocess` expects 2-D — EinopsError in `.generate()` for both official 1.5B checkpoints", "source_excerpt": "One addition from the tilelang side (tile-ai/tilelang#3071): the tilelang maintainers recommend using `T.dynamic` for the Mamba-3 MIMO kernel spec so a single compiled kernel serves arbitrary seqlens. Currently every distinct seqlen triggers a full ~7-8s JIT recompile (one cache key per shape), which makes token-by-token generation impractical on the MIMO path (~8s/token) independent of the `step(", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:11.579128Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/state-spaces/mamba/issues/1022#issuecomment-5384259745", "excerpt": "The tilelang-side companion issue (silent all-zeros MIMO kernel miscompilation on sm_121, compile-order-dependent) is now filed: https://github.com/tile-ai/tilelang/issues/3071", "login": "robertforbes68"}, {"source_url": "https://github.com/state-spaces/mamba/issues/1022#issuecomment-5431600555", "excerpt": "One addition from the tilelang side (tile-ai/tilelang#3071): the tilelang maintainers recommend using `T.dynamic` for the Mamba-3 MIMO kernel spec so a single compiled kernel serves arbitrary seqlens. Currently every distinct seqlen triggers a full ~7-8s JIT recompile (one cache key per shape), which makes token-by-token generation impractical on the MIMO path (~8s/token) independent of the `step(", "login": "robertforbes68"}, {"source_url": "https://github.com/state-spaces/mamba/issues/1022#issuecomment-5432020209", "excerpt": "Checkpoint observation while investigating what we initially misdiagnosed as a kernel bug (tile-ai/tilelang#3071, now resolved as not-tilelang): `mamba3-mimo-1.5b` has a content-triggered degenerate attractor. Greedy generation from \"Inventory record: the component serial number is CN-4821 … The serial number of that component is\" produces an endless \"000000…\" loop — reproducible across prompt var", "login": "robertforbes68"}, {"source_url": "https://github.com/state-spaces/mamba/issues/1022#issuecomment-5518700159", "excerpt": "Data point on the `T.dynamic` question, now that tilelang 0.1.14 is out (Sept 2). Same measurements posted to tile-ai/tilelang#3071.\n\n**Setup:** DGX Spark (GB10, sm_121, driver 580.173.02, torch 2.11 cu130), `mamba3-mimo-1.5b`, mamba-ssm git main (`e9594ce`), isolated `TILELANG_CACHE_DIR` so every new seqlen is a cold compile. Same script, same day; the only variables are the tilelang version and ", "login": "robertforbes68"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_004_v1_credibility@6534901b983d2bb1', 'signal-repo-597ab80a4c0e-1019', 'repo-597ab80a4c0e', 'discussion_inconclusive', '{"signal_id": "signal-repo-597ab80a4c0e-1019", "repository_id": "repo-597ab80a4c0e", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/state-spaces/mamba/issues/1019", "source_title": "No prebuilt wheels for sm_103 (B300) and sm_121 (GB10)", "source_excerpt": "No prebuilt wheels for sm_103 (B300) and sm_121 (GB10)\n## Problem\n\n`mamba-ssm` does not ship prebuilt wheels for new NVIDIA GPU architectures:\n- **sm_103** (B300 SXM6, GB300)\n- **sm_121** (GB10, DGX Spark / Project DIGITS)\n\nUsers must compile from source, which requires:\n1. Matching CUDA toolkit version (13.0+ for sm_121, 12.8+ for sm_103)\n2. Setting `TORCH_CUDA_ARCH_LIST` correctly\n3. Working aro", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:11.579200Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": []}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_004_v1_credibility@6534901b983d2bb1', 'signal-repo-597ab80a4c0e-1018', 'repo-597ab80a4c0e', 'discussion_inconclusive', '{"signal_id": "signal-repo-597ab80a4c0e-1018", "repository_id": "repo-597ab80a4c0e", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/state-spaces/mamba/issues/1018", "source_title": "mamba3 utils.py: PTX inline-asm helpers (cos_approx/sin_approx/tanh_approx) with NVPTX ''f'' constraints cannot compile on ROCm/AMDGPU", "source_excerpt": "mamba3 utils.py: PTX inline-asm helpers (cos_approx/sin_approx/tanh_approx) with NVPTX ''f'' constraints cannot compile on ROCm/AMDGPU\n## Summary\n\n`mamba_ssm/ops/triton/mamba3/utils.py` implements its fast trig/gating approximations (`cos_approx`, `sin_approx`, `tanh_approx`, `sech2_approx`, `sigmoid_approx`) with **NVIDIA PTX inline assembly** via `tl.inline_asm_elementwise(..., constraints=\"=f,f\")", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:11.580377Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/state-spaces/mamba/issues/1018#issuecomment-5302731436", "excerpt": "## Follow-up: PTX census + CPU paper-equation reference (both shipped here)\n\n### 1. PTX census — the fix is exactly 4 sites, complete for the numerics path\n\nGrep of the entire installed `mamba_ssm/ops/triton/mamba3/` package for `inline_asm_elementwise`:\n\n```\nutils.py:23   cos_approx   -> cos.approx.f32 $0, $1;    ACTIVE\nutils.py:43   sin_approx   -> sin.approx.f32 $0, $1;    ACTIVE\nutils.py:62   ", "login": "kryptodogg"}, {"source_url": "https://github.com/state-spaces/mamba/issues/1018#issuecomment-5305759505", "excerpt": "## Follow-up: ROCm half of the numerical-equivalence gate — measured profile for `tl.cos`/`tl.sin` (the proposed builtin swap)\n\nThe fix request asked that the `cos.approx` → `tl.cos`/`tl.sin` swap be verified numerically within fp16-accumulation tolerance on both targets, with an fp32 reference. On this ROCm box the PTX side cannot compile (that''s the boundary this issue is about), so the measurab", "login": "kryptodogg"}, {"source_url": "https://github.com/state-spaces/mamba/issues/1018#issuecomment-5306574785", "excerpt": "Follow-up: the ROCm-side numerical-equivalence gate now covers **all four** active PTX sites in `mamba3/utils.py`. Extending the cos/sin profile posted above with the tanh/sech2 arms, measured on gfx1031 (torch 2.13.0+rocm7.2, triton 3.7.1, AMD Radeon RX 6700 XT) with the same fp64-reference methodology, using the exact synthesis forms the swap proposes (`2*sigmoid(2x)-1`, `1-tanh^2`, both with th", "login": "kryptodogg"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_004_v1_credibility@6534901b983d2bb1', 'signal-repo-597ab80a4c0e-1017', 'repo-597ab80a4c0e', 'discussion_inconclusive', '{"signal_id": "signal-repo-597ab80a4c0e-1017", "repository_id": "repo-597ab80a4c0e", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/state-spaces/mamba/issues/1017", "source_title": "Mamba3 SISO kernel: 3-7.5% deviation from reference (heavy-tailed, masked by bf16 rtol=1e-1)", "source_excerpt": "Mamba3 SISO kernel: 3-7.5% deviation from reference (heavy-tailed, masked by bf16 rtol=1e-1)\n# Mamba-3 SISO kernel deviates from reference — heavy-tailed numerical errors\n\n## Summary\n`mamba3_siso_combined` (Triton) does not match `mamba3_siso_fwd_ref` (the reference\nimplementation in `tests/ops/triton/test_mamba3_siso.py`) at any tested config.\nRelative error is 3–7.5% across all settings; the dev", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:11.580460Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": []}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_004_v1_credibility@6534901b983d2bb1', 'signal-repo-14ac1351d084-40', 'repo-14ac1351d084', 'discussion_inconclusive', '{"signal_id": "signal-repo-14ac1351d084-40", "repository_id": "repo-14ac1351d084", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/deepsound-project/samplernn-pytorch/issues/40#issuecomment-698133329", "source_title": "Working training in colab but no sound", "source_excerpt": "Hi pabloriera, have you fix your problem?\r\n\r\nI also tried training the model using 2 hours'' music from a band, following the Readme, but without success.\r\nThen I tried to reproduce the piano example exactly the same as the Readme, but I still got nothing but clips.\r\n\r\nI was using a local server with tpu. I also wonder what is going wrong.", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:11.590938Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/deepsound-project/samplernn-pytorch/issues/40#issuecomment-671520483", "excerpt": "For me all the Userwarnings were worth fixing. For the sample generation, I have to admit that I didn''t succeed to generate as much good sounding sample as the Theano implementation (link here [https://github.com/soroushmehr/sampleRNN_ICLR2017](url)).\r\n\r\nMoreover, 14mins might be short for your Voice Dataset I think you should look for those 10 hours video. Also, when listening to the YouTube vide", "login": "BertSam"}, {"source_url": "https://github.com/deepsound-project/samplernn-pytorch/issues/40#issuecomment-671566431", "excerpt": "Ok, thanks for the info. I would try to fix the warnings, don''t now how.\r\n\r\nFirst I tried with the pianojazz video that lasts 3 hours, but I got the same results, so I switched to a short audio. I was hopping the model to overfitt to the audio at least.\r\n", "login": "pabloriera"}, {"source_url": "https://github.com/deepsound-project/samplernn-pytorch/issues/40#issuecomment-698133329", "excerpt": "Hi pabloriera, have you fix your problem?\r\n\r\nI also tried training the model using 2 hours'' music from a band, following the Readme, but without success.\r\nThen I tried to reproduce the piano example exactly the same as the Readme, but I still got nothing but clips.\r\n\r\nI was using a local server with tpu. I also wonder what is going wrong.", "login": "paranoid2droid"}, {"source_url": "https://github.com/deepsound-project/samplernn-pytorch/issues/40#issuecomment-698428882", "excerpt": "Hi, I could not work it out. I found a keras implementation and manage to\nhave acceptable results.\n\nEl jue., 24 sept. 2020 a las 3:05, Zhe Zhang (<notifications@github.com>)\nescribió:\n\n> Hi pabloriera, have you fix your problem?\n>\n> I also tried training the model using 2 hours'' music from a band,\n> following the Readme, but without success.\n> Then I tried to reproduce the piano example exactly th", "login": "pabloriera"}, {"source_url": "https://github.com/deepsound-project/samplernn-pytorch/issues/40#issuecomment-750510741", "excerpt": "Hi! Did anyone have any success implementing this notebook in a local environment?\r\n", "login": "Bjerken"}, {"source_url": "https://github.com/deepsound-project/samplernn-pytorch/issues/40#issuecomment-792599045", "excerpt": "285 epochs and still nothing but pops :(", "login": "nschmidtg"}, {"source_url": "https://github.com/deepsound-project/samplernn-pytorch/issues/40#issuecomment-989335891", "excerpt": "Hi, I tried to set it up in the local env, but for a small set of audio data, it samples out click noises and nothing else. Anybody got some good results, please share them here.\r\nBR", "login": "mukul74"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
