INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_008_openreview_2024_02_11_credibility@45573285332f69c4', 'signal-repo-b6bef96e5a3a-608', 'repo-b6bef96e5a3a', 'discussion_inconclusive', '{"signal_id": "signal-repo-b6bef96e5a3a-608", "repository_id": "repo-b6bef96e5a3a", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6030734517", "source_title": "Update for gpt-6 models", "source_excerpt": "I reproduced the lookup failure with `tiktoken==0.14.0` on macOS/Apple Silicon, Python 3.14.5. The installed `tiktoken/model.py` matches current `main` at `4e71bbe0c078468e00fefbf94b39849389f346e5` byte-for-byte.\n\nThis runs without API credentials or model calls:\n\n```python\nfrom tiktoken.model import encoding_name_for_model\n\nfor name in (\"gpt-6-astra\", \"gpt-6-sol\", \"gpt-6-luna\", \"gpt-5.6-sol\", \"gp", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:28.114749Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-5957858605", "excerpt": "@hauntsaninja Do you still work here? Any update on this issue?", "login": "impredicative"}, {"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6030734517", "excerpt": "I reproduced the lookup failure with `tiktoken==0.14.0` on macOS/Apple Silicon, Python 3.14.5. The installed `tiktoken/model.py` matches current `main` at `4e71bbe0c078468e00fefbf94b39849389f346e5` byte-for-byte.\n\nThis runs without API credentials or model calls:\n\n```python\nfrom tiktoken.model import encoding_name_for_model\n\nfor name in (\"gpt-6-astra\", \"gpt-6-sol\", \"gpt-6-luna\", \"gpt-5.6-sol\", \"gp", "login": "rksharma-owg"}, {"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6030956362", "excerpt": "@hintz-openai Does anyone still work here?", "login": "impredicative"}, {"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6071803831", "excerpt": "https://github.com/williamliu-ai/token-count-compare/commit/8d8a2178538bb37beb548fc37378135e4ff4b0c8 is an experiment that strongly suggests that GPT-6 models use the same tokenizer as GPT-5:\n\n> - All seven GPT models (5.5, 5.6 Sol/Terra/Luna, 6 Astra/Sol/Luna) report 44,794 tokens and match each other on every one of the 31 fixtures. GPT-6 introduces no input-count change on this corpus.\n", "login": "simonw"}, {"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6072178497", "excerpt": "> suggests that GPT-6 models use the same tokenizer as GPT-5\n\nThat may be so, and many users already fallback to the GPT-5 encoding, but this issue is more about enforcing discipline wrt updates. A lack of timely updates is a recurring problem with tiktoken. It''s not the first time they''ve failed to update the package. Every single time they have to be begged to add the new model. I''ll let you get", "login": "impredicative"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_008_openreview_2024_02_11_credibility@45573285332f69c4', 'signal-repo-b6bef96e5a3a-536', 'repo-b6bef96e5a3a', 'discussion_inconclusive', '{"signal_id": "signal-repo-b6bef96e5a3a-536", "repository_id": "repo-b6bef96e5a3a", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/openai/tiktoken/issues/536", "source_title": "Encoding.is_special_token() raises AttributeError - undefined attribute _special_token_values", "source_excerpt": "Encoding.is_special_token() raises AttributeError - undefined attribute _special_token_values\n## Description\n\n`Encoding.is_special_token()` in `tiktoken/core.py` (line 367) references `self._special_token_values` which is never defined in `__init__` or anywhere else in the class.\n\nAny call to this method immediately raises `AttributeError`.\n\n## Steps to reproduce\n\n```python\nimport tiktoken\n\nenc = ", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:41:28.117331Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/openai/tiktoken/issues/536#issuecomment-4456996874", "excerpt": "Thanks, this was caused by an incomplete redaction from the internal codebase. Fixed in the latest release", "login": "hauntsaninja"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_008_openreview_2024_02_11_credibility@45573285332f69c4', 'signal-repo-b6bef96e5a3a-530', 'repo-b6bef96e5a3a', 'discussion_inconclusive', '{"signal_id": "signal-repo-b6bef96e5a3a-530", "repository_id": "repo-b6bef96e5a3a", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/openai/tiktoken/issues/530", "source_title": "encode_ordinary_batch — reproducible multi-second tail stalls on 32-core box (o200k_base, num_threads=8)", "source_excerpt": "encode_ordinary_batch — reproducible multi-second tail stalls on 32-core box (o200k_base, num_threads=8)\n\nRunning `encode_ordinary_batch` with its default `num_threads=8` on a 32-core Sapphire Rapids box, I''m seeing large tail spikes on the slowest run of every 10-run batch. Same input, same build, the worst run is 1.1× to 7.6× slower than the median depending on corpus. Multilingual text is the w", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:28.118130Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/openai/tiktoken/issues/530#issuecomment-4502961983", "excerpt": "I''ve put up a benchmark harness based on the methodology you described in this issue — PR #548.\nIt measures median and worst-of-N wall-clock time across four synthetic corpora (english prose, python source, multilingual+emoji, random ascii) with configurable runs, batch size, encoding, and thread counts. No external data files required — corpora are generated at runtime.\nHappy to extend it if you ", "login": "alobroke"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_008_openreview_2024_02_11_credibility@45573285332f69c4', 'signal-repo-b6bef96e5a3a-513', 'repo-b6bef96e5a3a', 'discussion_inconclusive', '{"signal_id": "signal-repo-b6bef96e5a3a-513", "repository_id": "repo-b6bef96e5a3a", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/openai/tiktoken/issues/513", "source_title": "[Bug] tiktoken 0.9.0 ignores TIKTOKEN_OFFLINE and TIKTOKEN_CACHE_DIR, still attempts network download", "source_excerpt": "[Bug] tiktoken 0.9.0 ignores TIKTOKEN_OFFLINE and TIKTOKEN_CACHE_DIR, still attempts network download\n### Bug Description\n在离线环境（无互联网连接）下，`tiktoken==0.9.0` 即使已经设置了 `TIKTOKEN_CACHE_DIR` 环境变量且本地缓存文件完整，仍然会尝试从网络下载编码文件，导致 `requests.exceptions.ConnectionError` 异常。\n\n降级到 `tiktoken==0.5.0` 后问题消失，说明 0.9.0 版本的缓存机制存在回归。\n\n### Steps to Reproduce\n1. **准备环境**（在有网机器上）：\n   ```bash\n   # 下载编码文件到默认缓存目录\n   mkdir -p ~/.c", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:28.118785Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/openai/tiktoken/issues/513#issuecomment-4525023762", "excerpt": "Hi! Triaging older issues — I think this is a cache-layout misunderstanding rather than a regression. Want to lay out the evidence so you can confirm before closing.\n\nTwo things going on:\n\n1. **`TIKTOKEN_OFFLINE` is not a supported env var in any released tiktoken.** The loader only reads `TIKTOKEN_CACHE_DIR` and the older `DATA_GYM_CACHE_DIR` — see `tiktoken/load.py:37-43` on `main` (commit `fa8b", "login": "jbbqqf"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
