INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_008_openreview_2024_02_11_credibility@45573285332f69c4', 'ca-5e0ff9b79d89db36', 'f-signal-repo-b6bef96e5a3a-608', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-b6bef96e5a3a-608", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-b6bef96e5a3a-608", "repository_id": "repo-b6bef96e5a3a", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6030734517", "source_title": "Update for gpt-6 models", "source_excerpt": "I reproduced the lookup failure with `tiktoken==0.14.0` on macOS/Apple Silicon, Python 3.14.5. The installed `tiktoken/model.py` matches current `main` at `4e71bbe0c078468e00fefbf94b39849389f346e5` byte-for-byte.\n\nThis runs without API credentials or model calls:\n\n```python\nfrom tiktoken.model import encoding_name_for_model\n\nfor name in (\"gpt-6-astra\", \"gpt-6-sol\", \"gpt-6-luna\", \"gpt-5.6-sol\", \"gp", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:28.114749Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-5957858605", "excerpt": "@hauntsaninja Do you still work here? Any update on this issue?", "login": "impredicative"}, {"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6030734517", "excerpt": "I reproduced the lookup failure with `tiktoken==0.14.0` on macOS/Apple Silicon, Python 3.14.5. The installed `tiktoken/model.py` matches current `main` at `4e71bbe0c078468e00fefbf94b39849389f346e5` byte-for-byte.\n\nThis runs without API credentials or model calls:\n\n```python\nfrom tiktoken.model import encoding_name_for_model\n\nfor name in (\"gpt-6-astra\", \"gpt-6-sol\", \"gpt-6-luna\", \"gpt-5.6-sol\", \"gp", "login": "rksharma-owg"}, {"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6030956362", "excerpt": "@hintz-openai Does anyone still work here?", "login": "impredicative"}, {"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6071803831", "excerpt": "https://github.com/williamliu-ai/token-count-compare/commit/8d8a2178538bb37beb548fc37378135e4ff4b0c8 is an experiment that strongly suggests that GPT-6 models use the same tokenizer as GPT-5:\n\n> - All seven GPT models (5.5, 5.6 Sol/Terra/Luna, 6 Astra/Sol/Luna) report 44,794 tokens and match each other on every one of the 31 fixtures. GPT-6 introduces no input-count change on this corpus.\n", "login": "simonw"}, {"source_url": "https://github.com/openai/tiktoken/issues/608#issuecomment-6072178497", "excerpt": "> suggests that GPT-6 models use the same tokenizer as GPT-5\n\nThat may be so, and many users already fallback to the GPT-5 encoding, but this issue is more about enforcing discipline wrt updates. A lack of timely updates is a recurring problem with tiktoken. It''s not the first time they''ve failed to update the package. Every single time they have to be begged to add the new model. I''ll let you get", "login": "impredicative"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/openai/tiktoken/issues/608#issuecomment-6030734517"], "checked_at": "2026-10-09T04:41:28.114749Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
