rtainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_008_openreview_2024_02_11_credibility@45573285332f69c4', 'ca-5e0ff9b79d89db36', 'f-signal-repo-b6bef96e5a3a-530', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-b6bef96e5a3a-530", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-b6bef96e5a3a-530", "repository_id": "repo-b6bef96e5a3a", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/openai/tiktoken/issues/530", "source_title": "encode_ordinary_batch — reproducible multi-second tail stalls on 32-core box (o200k_base, num_threads=8)", "source_excerpt": "encode_ordinary_batch — reproducible multi-second tail stalls on 32-core box (o200k_base, num_threads=8)\n\nRunning `encode_ordinary_batch` with its default `num_threads=8` on a 32-core Sapphire Rapids box, I''m seeing large tail spikes on the slowest run of every 10-run batch. Same input, same build, the worst run is 1.1× to 7.6× slower than the median depending on corpus. Multilingual text is the w", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:28.118130Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/openai/tiktoken/issues/530#issuecomment-4502961983", "excerpt": "I''ve put up a benchmark harness based on the methodology you described in this issue — PR #548.\nIt measures median and worst-of-N wall-clock time across four synthetic corpora (english prose, python source, multilingual+emoji, random ascii) with configurable runs, batch size, encoding, and thread counts. No external data files required — corpora are generated at runtime.\nHappy to extend it if you ", "login": "alobroke"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/openai/tiktoken/issues/530"], "checked_at": "2026-10-09T04:41:28.118130Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_008_openreview_2024_02_11_credibility@45573285332f69c4', 'ca-5e0ff9b79d89db36', 'f-signal-repo-b6bef96e5a3a-513', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-b6bef96e5a3a-513", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-b6bef96e5a3a-513", "repository_id": "repo-b6bef96e5a3a", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/openai/tiktoken/issues/513", "source_title": "[Bug] tiktoken 0.9.0 ignores TIKTOKEN_OFFLINE and TIKTOKEN_CACHE_DIR, still attempts network download", "source_excerpt": "[Bug] tiktoken 0.9.0 ignores TIKTOKEN_OFFLINE and TIKTOKEN_CACHE_DIR, still attempts network download\n### Bug Description\n在离线环境（无互联网连接）下，`tiktoken==0.9.0` 即使已经设置了 `TIKTOKEN_CACHE_DIR` 环境变量且本地缓存文件完整，仍然会尝试从网络下载编码文件，导致 `requests.exceptions.ConnectionError` 异常。\n\n降级到 `tiktoken==0.5.0` 后问题消失，说明 0.9.0 版本的缓存机制存在回归。\n\n### Steps to Reproduce\n1. **准备环境**（在有网机器上）：\n   ```bash\n   # 下载编码文件到默认缓存目录\n   mkdir -p ~/.c", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:28.118785Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/openai/tiktoken/issues/513#issuecomment-4525023762", "excerpt": "Hi! Triaging older issues — I think this is a cache-layout misunderstanding rather than a regression. Want to lay out the evidence so you can confirm before closing.\n\nTwo things going on:\n\n1. **`TIKTOKEN_OFFLINE` is not a supported env var in any released tiktoken.** The loader only reads `TIKTOKEN_CACHE_DIR` and the older `DATA_GYM_CACHE_DIR` — see `tiktoken/load.py:37-43` on `main` (commit `fa8b", "login": "jbbqqf"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/openai/tiktoken/issues/513"], "checked_at": "2026-10-09T04:41:28.118785Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
