INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_009_openreview_2024_02_11_credibility@724887c16ff0326a', 'signal-repo-3fe3c4210beb-4', 'repo-3fe3c4210beb', 'discussion_inconclusive', '{"signal_id": "signal-repo-3fe3c4210beb-4", "repository_id": "repo-3fe3c4210beb", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/LabForComputationalVision/memorization_generalization_in_diffusion_models/issues/4", "source_title": "Preprocessing for the celebA dataset", "source_excerpt": "Preprocessing for the celebA dataset\nHi, I''m trying to reproduce the result but don''t seem to able to get the same training set and testing set as you do. I followed the other issue #3 and the provided code code/celebA_to_torch.py but got something that''s a bit off:\r\n\r\nSpecifically, I downloaded img_align_celeba from the website and used their provided list_eval_partition.txt to separate training ", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:41:33.513912Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/LabForComputationalVision/memorization_generalization_in_diffusion_models/issues/4#issuecomment-2342951571", "excerpt": "Hi,\r\n\r\nI also tried running the pre-processing code on all 202,599 images, but after using the remove repeats function, I ended up with only 196,018 images of size 80x80, instead of the 198,650 images of 80x80 mentioned in your checkpoint. Could you clarify why this discrepancy occurs, or if there''s a step I might have missed? Did the remove repeats function use 20X20 downsampled images (as writte", "login": "chenzeno"}, {"source_url": "https://github.com/LabForComputationalVision/memorization_generalization_in_diffusion_models/issues/4#issuecomment-2343127461", "excerpt": "I would like to jump in with a related problem. \r\nI noticed that in `Demo_UNet_CelebA80x80.ipynb` in the `Load datasets` (cell No. 5) the split is determined by the order of the images loaded (since `train = data[0:N]`, and `test = data[-N:]`.  \r\nSince the images were loaded in `celebA_to_torch.py:L17`>`dataloader_func.py:load_CelebA_dataset` by simply using `os.listdir`, the order of the loaded i", "login": "HilaManor"}, {"source_url": "https://github.com/LabForComputationalVision/memorization_generalization_in_diffusion_models/issues/4#issuecomment-2353456823", "excerpt": "> Hi, I''m trying to reproduce the result but don''t seem to able to get the same training set and testing set as you do. I followed the other issue #3 and the provided code code/celebA_to_torch.py but got something that''s a bit off:\r\n> \r\n> Specifically, I downloaded img_align_celeba from the website and used their provided list_eval_partition.txt to separate training and testing sets. There are 202", "login": "Zahra-Kadkhodaie"}, {"source_url": "https://github.com/LabForComputationalVision/memorization_generalization_in_diffusion_models/issues/4#issuecomment-2353478887", "excerpt": "> Hi,\r\n> \r\n> I also tried running the pre-processing code on all 202,599 images, but after using the remove repeats function, I ended up with only 196,018 images of size 80x80, instead of the 198,650 images of 80x80 mentioned in your checkpoint. Could you clarify why this discrepancy occurs, or if there''s a step I might have missed? Did the remove repeats function use 20X20 downsampled images (as ", "login": "Zahra-Kadkhodaie"}, {"source_url": "https://github.com/LabForComputationalVision/memorization_generalization_in_diffusion_models/issues/4#issuecomment-2353481862", "excerpt": "> I would like to jump in with a related problem. I noticed that in `Demo_UNet_CelebA80x80.ipynb` in the `Load datasets` (cell No. 5) the split is determined by the order of the images loaded (since `train = data[0:N]`, and `test = data[-N:]`. Since the images were loaded in `celebA_to_torch.py:L17`>`dataloader_func.py:load_CelebA_dataset` by simply using `os.listdir`, the order of the loaded imag", "login": "Zahra-Kadkhodaie"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
