INSERT INTO credibility_r2.credibility_claims (case_id, credibility_claim_id, paper_version_id, payload) VALUES ('paper_014_openreview_2024_02_11_credibility@3f061307fafe206f', 'paper_014_openreview_2024_02_11_credibility_claim_001', 'paper_014_openreview_2024_02_11', '{"credibility_claim_id": "paper_014_openreview_2024_02_11_credibility_claim_001", "paper_version_id": "paper_014_openreview_2024_02_11", "source_chunk_id": "paper_014_openreview_2024_02_11_chunk_0001", "claim_text": "On a set of public benchmarks with datasets up to several million objects, TabR marks a big step forward for tabularDL:itdemonstratesthebestaverageperformanceamongtabularDLmodels, becomes the new state-of-the-art on several datasets, and even outperforms GBDT models on the recently proposed “GBDT-friendly” benchmark (see Figure 1).", "claim_type": "performance", "importance": "major", "verifiability": true, "dedup_group_id": null, "page_number": 1, "extraction_source": "existing_ai_semantic_descriptor_alignment", "review_status": "reviewed", "exclusion_reason": null}'::jsonb) ON CONFLICT (case_id, credibility_claim_id) DO NOTHING;
