INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_014_openreview_2024_02_11_credibility@3f061307fafe206f', 'ca-603af368e368a8f6', 'f-signal-repo-7c981acc9a73-8', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-7c981acc9a73-8", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-7c981acc9a73-8", "repository_id": "repo-7c981acc9a73", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/somepago/saint/issues/8", "source_title": "Code for interpretability", "source_excerpt": "Code for interpretability\nHello,\r\n\r\nThanks for this repo! Do you plan to release the code you used to plot intersample attention and self attention as in the paper (section 5.2)? I would like to reproduce the figure 3.", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:43:06.775674Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/somepago/saint/issues/8#issuecomment-945202273", "excerpt": "Hi Fabien, I will release the attention plotting code in the next version. I am busy with another project rn, I am targeting the end of November for this. If you need it urgently let me know. ", "login": "somepago"}, {"source_url": "https://github.com/somepago/saint/issues/8#issuecomment-945455147", "excerpt": "Thanks for your answer! I understand your time is precious but it would help me a lot if you could just share the code for attention plots.", "login": "Fabien-Couthouis"}, {"source_url": "https://github.com/somepago/saint/issues/8#issuecomment-987499173", "excerpt": "@somepago Wold be great help if you can share the code for interpretability. I have reached out to you by email as well. ", "login": "bdubey"}, {"source_url": "https://github.com/somepago/saint/issues/8#issuecomment-1106050919", "excerpt": "Hello Gowthami,\r\n\r\nThanks for this project. It will be of great help to get the attention plotting code for the SAINT implementation.", "login": "isamgul"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/somepago/saint/issues/8"], "checked_at": "2026-10-09T04:43:06.775674Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_014_openreview_2024_02_11_credibility@3f061307fafe206f', 'ca-603af368e368a8f6', 'f-signal-repo-7c981acc9a73-1', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-7c981acc9a73-1", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-7c981acc9a73-1", "repository_id": "repo-7c981acc9a73", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/somepago/saint/issues/1", "source_title": "Benchmark results difference", "source_excerpt": "Benchmark results difference\nHi,\r\nI was trying to reproduce the benchmark (xgboost and lightgbm) results but i can''t get the same showed in your paper.\r\n\r\nI used this to split the dataset in train, valid and test:\r\nhttps://github.com/somepago/saint/blob/e0ee763b0c23136ae03fa7cff71ff3b2ce4ba647/data.py#L190\r\n\r\nI used early stop on validation and collect test performance as final results and rerun t", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:43:08.960139Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/somepago/saint/issues/1#issuecomment-861703727", "excerpt": "Thanks for doing this hyperparameter tuning!  We did not conduct much tuning either for gradient boosting methods or for SAINT (in terms of hyperparameters or regularizers), and we use the numbers from original papers when they exist.  In fact, we did not try different regularizers on SAINT at all.  We definitely plan to spend some time hyperparameter tuning at both for our own method and for comp", "login": "somepago"}, {"source_url": "https://github.com/somepago/saint/issues/1#issuecomment-862115248", "excerpt": "> Thanks for doing this hyperparameter tuning!  We did not conduct much tuning either for gradient boosting methods or for SAINT (in terms of hyperparameters or regularizers), and we use the numbers from original papers when they exist.  In fact, we did not try different regularizers on SAINT at all.  We definitely plan to spend some time hyperparameter tuning at both for our own method and for co", "login": "DavideStenner"}, {"source_url": "https://github.com/somepago/saint/issues/1#issuecomment-862379426", "excerpt": "We will do an extensive hyper parameter search with early stopping in the next arxiv update. Closing the issue for now since it is not related to the code.", "login": "somepago"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/somepago/saint/issues/1"], "checked_at": "2026-10-09T04:43:08.960139Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
