INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_016_openreview_2024_02_11_credibility@c5473c69ff6dd13d', 'ca-b37f0ab0c9658b4f', 'f-signal-repo-105c7fa85be7-1', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-105c7fa85be7-1", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-105c7fa85be7-1", "repository_id": "repo-105c7fa85be7", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/jannerm/mbpo/issues/1", "source_title": "When I tried to reproduce the project environment with $ conda env create -f environment/gpu-env.yml encountered some problems", "source_excerpt": "When I tried to reproduce the project environment with $ conda env create -f environment/gpu-env.yml encountered some problems\nFailed to build mujoco-py\r\nERROR: flask 1.1.1 has requirement Werkzeug>=0.15, but you''ll have werkzeug 0.14.1 which is incompatible.\r\nERROR: awscli 1.16.67 has requirement PyYAML<=3.13,>=3.10, but you''ll have pyyaml 4.2b4 which is incompatible.", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:43:53.606571Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/jannerm/mbpo/issues/1#issuecomment-518003851", "excerpt": "Maybe it need to clearly specify the version of flask and modify version of awscli/PyYAML in requirements.txt", "login": "cmciris"}, {"source_url": "https://github.com/jannerm/mbpo/issues/1#issuecomment-518093951", "excerpt": "Thanks for the heads-up. The version conflicts should be fixed as of commit 3f