INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_027_openreview_2024_02_11_credibility@c032d369edf1fe18', 'ca-24a1b0da7c402e76', 'f-signal-repo-9b3f92ad94a6-260', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-9b3f92ad94a6-260", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-9b3f92ad94a6-260", "repository_id": "repo-9b3f92ad94a6", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/260", "source_title": "[lr discussion]", "source_excerpt": "[lr discussion]\nI try to reproduce aplaca, the data and configuration used are basically consistent with the original open source code, why my lr has so many cycles? I understand that when I use cosine, lr should not have cycles, but gradually decrease to 0.\r\n![Uploading image.png…]()\r\n", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:48:30.273664Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/260#issuecomment-1541203512", "excerpt": "![企业微信截图_16836860559634](https://github.com/tatsu-lab/stanford_alpaca/assets/48375360/39e00c87-508a-41fc-bd0d-8f46496856bb)\r\n", "login": "echoht"}, {"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/260#issuecomment-1543224465", "excerpt": "I have known why my lr curve like this, because I use the default value of deepspeed''s gradient_accumulation_steps, which is different from my  TrainingArguments 8.", "login": "echoht"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/tatsu-lab/stanford_alpaca/issues/260"], "checked_at": "2026-10-09T04:48:30.273664Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_027_openreview_2024_02_11_credibility@c032d369edf1fe18', 'ca-24a1b0da7c402e76', 'f-signal-repo-9b3f92ad94a6-236', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-9b3f92ad94a6-236", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-9b3f92ad94a6-236", "repository_id": "repo-9b3f92ad94a6", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1623153814", "source_title": "Training loss curve like stairs.", "source_excerpt": "> <img alt=\"image\" width=\"1433\" src=\"https://user-images.githubusercontent.com/5069709/237271945-51570d78-dbaf-4ce4-8c72-52da0d99241b.png\">\r\n> This is the loss curve I have.\r\n\r\n@yuanzhedong  Hi, is this kind of loss curve normal or expected ? I am reproducing the finetuning of llama-7b and want to see whether there is something going wrong.", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:48:30.280816Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1518336580", "excerpt": "The cmd I''m using\r\n```\r\ntorchrun --nproc_per_node=8 train.py \\\r\n    --model_name_or_path ./llama-7b-hf \\\r\n    --data_path ./alpaca_data.json \\\r\n    --bf16 True \\\r\n    --output_dir /workspace/code/output \\\r\n    --num_train_epochs 3 \\\r\n    --per_device_train_batch_size 4 \\\r\n    --per_device_eval_batch_size 4 \\\r\n    --gradient_accumulation_steps 8 \\\r\n    --evaluation_strategy \"no\" \\\r\n    --save_strat", "login": "yuanzhedong"}, {"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1536021238", "excerpt": "Hi! Have you solved the problem?", "login": "WooKimm"}, {"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1540087324", "excerpt": "hi can you share the scale of training loss?\r\nThe following is mine. The loss of the beginning is very big!!  I use deepspeed and gradient checkpointing.\r\n![image](https://github.com/tatsu-lab/stanford_alpaca/assets/48375360/4fe1ecef-3030-483a-8d33-cb2df888da0b)\r\n\r\n", "login": "echoht"}, {"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1541107471", "excerpt": "I think [this](https://github.com/huggingface/transformers/issues/18730#issuecomment-1229769519) may explain why. Basically the dataset is too small and it kind of remember the dataset, so for the second time the model sees the same data again the loss will dive.", "login": "yuanzhedong"}, {"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1541175310", "excerpt": "I have the question about my beginning loss, which is about 8. This phenomenon is very strange. \r\nWhat are the factors that lead to this kind of big loss?", "login": "echoht"}, {"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1541301128", "excerpt": "<img width=\"1433\" alt=\"image\" src=\"https://github.com/tatsu-lab/stanford_alpaca/assets/5069709/51570d78-dbaf-4ce4-8c72-52da0d99241b\">\r\n\r\nThis is the loss curve I have.", "login": "yuanzhedong"}, {"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1560963540", "excerpt": "Same loss curve. ", "login": "ftgreat"}, {"source_url": "https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1623153814", "excerpt": "> <img alt=\"image\" width=\"1433\" src=\"https://user-images.githubusercontent.com/5069709/237271945-51570d78-dbaf-4ce4-8c72-52da0d99241b.png\">\r\n> This is the loss curve I have.\r\n\r\n@yuanzhedong  Hi, is this kind of loss curve normal or expected ? I am reproducing the finetuning of llama-7b and want to see whether there is something going wrong.", "login": "zycheiheihei"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/tatsu-lab/stanford_alpaca/issues/236#issuecomment-1623153814"], "checked_at": "2026-10-09T04:48:30.280816Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
