INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_037_iclr_2026_proceedings_credibility@0cab77dcd758e940', 'ca-f28504ec833d23f1', 'f-signal-repo-d330f61f607f-2337', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-d330f61f607f-2337", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-d330f61f607f-2337", "repository_id": "repo-d330f61f607f", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/rlworkgroup/garage/issues/2337", "source_title": "Reproducibility Issue of Atari, and Fetch tasks", "source_excerpt": "Reproducibility Issue of Atari, and Fetch tasks\nHey all,\r\n\r\nI am having some trouble reproducing the baseline numbers on both Atari and Fetch (Push/Pick-and-Place/Slide) tasks. \r\nAlthough, the same code works for Pong, Enduro, it seems to not reproduce numbers for other environments such as Breakout, Space Invaders (attached image below), and many more. These baseline numbers close resemble the fi", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:51:52.948125Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": []}, "internal_evidence": [], "external_source_urls": ["https://github.com/rlworkgroup/garage/issues/2337"], "checked_at": "2026-10-09T04:51:52.948125Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_037_iclr_2026_proceedings_credibility@0cab77dcd758e940', 'ca-f28504ec833d23f1', 'f-signal-repo-d330f61f607f-2332', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-d330f61f607f-2332", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-d330f61f607f-2332", "repository_id": "repo-d330f61f607f", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/rlworkgroup/garage/issues/2332", "source_title": "Reproducibility issue", "source_excerpt": "Reproducibility issue\nHi all, I''ve used the deterministic.set_seed but still get different results. It seems that the samples that start from itr2 become different (itr0 & itr1 are the same). Do you have ideas about this issue?", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:51:53.356056Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/rlworkgroup/garage/issues/2332#issuecomment-1298347397", "excerpt": "I think you need to set environment seed too as follows:\r\n\r\n`\r\n    env._env.seed(seed)\r\n    env.action_space.seed(seed)\r\n`", "login": "sadegh16"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/rlworkgroup/garage/issues/2332"], "checked_at": "2026-10-09T04:51:53.356056Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_037_iclr_2026_proceedings_credibility@0cab77dcd758e940', 'ca-f28504ec833d23f1', 'f-signal-repo-d330f61f607f-2302', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-d330f61f607f-2302", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-d330f61f607f-2302", "repository_id": "repo-d330f61f607f", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/rlworkgroup/garage/issues/2302", "source_title": "Log Directory Issue in wrap_experiment", "source_excerpt": "Log Directory Issue in wrap_experiment\nThere appears to be a bug in wrap_experiment, where the function to create a file to store an archive of the launcher''s git repo fails.\r\n\r\nTraceback:\r\n\r\n```\r\ntar (child): data/local/experiment/PONGNoFrameskip-v4_2/launch_archive.tar.xz: Cannot open: No such file or directory\r\ntar (child): Error is not recoverable: exiting now\r\ntar: data/local/experiment/PONGN", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:52:00.116465Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/rlworkgroup/garage/issues/2302#issuecomment-930700711", "excerpt": "That''s strange. It might be best if we change the default argument of `archive_launch_repo` to `False`.\r\nI imagine this could be caused by the data directory not being writable, or perhaps from tar not being able to use xz.\r\nThe tar command still looks correct, although it''s conceivably also possible that `git` produced an unusual file list in some way.\r\nThere are [several test](https://github.com", "login": "krzentner"}, {"source_url": "https://github.com/rlworkgroup/garage/issues/2302#issuecomment-930706455", "excerpt": "It''s writable as far as I can tell -- if I run\r\n\r\n```if [ -w ` pwd ` ]; then echo \"WRITABLE\"; else echo \"NOT WRITABLE\"; fi```\r\n\r\nin `$git_root_path$/data/local/experiment`\r\nit spits out WRITABLE.\r\n\r\nNot sure how to check whether tar can use xz.", "login": "ahalev"}, {"source_url": "https://github.com/rlworkgroup/garage/issues/2302#issuecomment-930706554", "excerpt": "Oh, I see what happened. `wrap_experiment` expects `log_dir` to be an absolute path (and sets it to an absolute path by default), but this example explicitly sets it to a relative path. The `tar` command is always run in the git repo root, so if the example is run from a git repo but not from the root, then the log directory doesn''t exists and the tar command fails.\r\n\r\nProbably `ExperimentWrapper`", "login": "krzentner"}, {"source_url": "https://github.com/rlworkgroup/garage/issues/2302#issuecomment-931832768", "excerpt": "Yes, it works with `archive_launch_repo=False`. Bizarrely, I copied the entire content of `dqn_atari.py` to a different folder outside of the repo and it works there with `archive_launch_repo=True`.", "login": "ahalev"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/rlworkgroup/garage/issues/2302"], "checked_at": "2026-10-09T04:52:00.116465Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_037_iclr_2026_proceedings_credibility@0cab77dcd758e940', 'ca-f28504ec833d23f1', 'f-signal-repo-94e877f2863f-3', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-94e877f2863f-3", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-94e877f2863f-3", "repository_id": "repo-94e877f2863f", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/WEIRDLabUW/STRAP/issues/3", "source_title": "Paper result reproduce", "source_excerpt": "Paper result reproduce\nHi, thanks for your wonderful work. I was trying to reproduce the paper results. I see the README file mentions code selects only 3 demos by default but your [code]( https://github.com/WEIRDLabUW/STRAP/blob/9b3a9b179d6fd974e5e7c04512ddff4de73501eb/strap/retrieval/retrieval.py#L20) shows 5.\n\nalso why only retrieve from [this](https://github.com/WEIRDLabUW/STRAP/blob/9b3a9b179", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:52:11.073593Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/WEIRDLabUW/STRAP/issues/3#issuecomment-3819929859", "excerpt": "Hey, sorry for taking so long to respond.\nFor your first question, thanks for pointing it out! There is a typo in our README. For our simulation experiments, we used 5 demonstrations, and for the real experiments, we used 3 (this is reflected accurately in the paper). For your second question, because we are training a single-task policy, we set the \"task_dataset_filter\" to be the specific task we", "login": "JacobB33"}, {"source_url": "https://github.com/WEIRDLabUW/STRAP/issues/3#issuecomment-3827487173", "excerpt": "Hi, thanks for getting back to me. Could you please clarify the single task policy? so you are creating the task dataset from only one task (5 demos) at a time where let''s say you get 20 segments. then you retrieve similar patterns from the entire offline dataset? and you repeat this for all 10 tasks?", "login": "zillur01"}, {"source_url": "https://github.com/WEIRDLabUW/STRAP/issues/3#issuecomment-3827499583", "excerpt": "Yeah! We get 5 demonstrations from the single task dataset, then split it up into sub trajectories and then retrieve from the offline dataset. The resulting policy is trained to be a single task expert on the target task. For our libero experiments, we trained a single task expert for each of the 10 libero tasks. ", "login": "JacobB33"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/WEIRDLabUW/STRAP/issues/3"], "checked_at": "2026-10-09T04:52:11.073593Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
