INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_043_iclr_2026_proceedings_credibility@a33e49d02fb6ac68', 'signal-repo-d8145bb67a00-9699', 'repo-d8145bb67a00', 'discussion_inconclusive', '{"signal_id": "signal-repo-d8145bb67a00-9699", "repository_id": "repo-d8145bb67a00", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/pytorch/vision/issues/9699", "source_title": "CUDA decode_jpeg can overwrite memory that queued work on the current stream still reads", "source_excerpt": "CUDA decode_jpeg can overwrite memory that queued work on the current stream still reads\n### 🐛 Describe the bug\n\n`decode_jpeg(..., device=\"cuda\")` allocates its output with the caching allocator, which assigns the block to the current stream. nvJPEG then writes the output on the decoder''s private stream. The decoder makes the current stream wait for that stream after the decode (`syncStreams(decod", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:54:26.655887Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/pytorch/vision/issues/9699#issuecomment-6056532050", "excerpt": "Thanks for the report @zhiyuanw101. I think this is the exact same bug as https://github.com/meta-pytorch/torchcodec/pull/1634 which was fixed in torchcodec. The torchvision decoders are deprecated and users should migrate to torchcodec now (see e.g. our [migration guide](https://meta-pytorch.org/torchcodec/main/generated_examples/migration/torchvision_migration.html)). \n\nI''ll close this as we won", "login": "NicolasHug"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_043_iclr_2026_proceedings_credibility@a33e49d02fb6ac68', 'signal-repo-d8145bb67a00-9687', 'repo-d8145bb67a00', 'discussion_inconclusive', '{"signal_id": "signal-repo-d8145bb67a00-9687", "repository_id": "repo-d8145bb67a00", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/pytorch/vision/issues/9687", "source_title": "Use a safe extraction filter for dataset tar archives", "source_excerpt": "Use a safe extraction filter for dataset tar archives\n> **AI-assisted issue conversion (Codex).** Original report and reproduction by @0xSaud; all credit belongs to the original reporter.\n>\n> Source: https://github.com/pytorch/pytorch/security/advisories/GHSA-m4rq-h4j7-8887\n>\n> The reporter identifies `_extract_tar()` calling `tar.extractall(to_path)` without an explicit extraction filter. On Pyth", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:54:27.163794Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/pytorch/vision/issues/9687#issuecomment-5982083159", "excerpt": "I reproduced the tar path traversal and opened #9693 with a fix. It uses the stdlib data filter where available, adds path/link validation around it, and keeps older supported Python versions safe with a validated extraction fallback. Tests cover ../ entries, absolute paths, and outside-pointing symlinks; focused standalone checks pass. Full repository pytest is running in upstream CI because this", "login": "lindicaphxag-tech"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
