INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_044_iclr_2026_proceedings_credibility@5b8574e4b5059838', 'ca-3e020a72473c5923', 'f-signal-repo-d4c01d613411-99', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-d4c01d613411-99", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-d4c01d613411-99", "repository_id": "repo-d4c01d613411", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/99", "source_title": "what''s the specific meaning of dsir?", "source_excerpt": "what''s the specific meaning of dsir?\nI am trying to reproduce this repo on my macOS, and I don''t have a aws account .can i get your help, i''d  appreciate it\r\n<img width=\"475\" alt=\"截屏2024-01-16 14 20 30\" src=\"https://github.com/togethercomputer/RedPajama-Data/assets/112547090/0358ffe7-e5e3-4d37-9f1e-3a61f16b068f\">\r\n", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:54:42.247369Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/99#issuecomment-1893275000", "excerpt": "Hi @BBetteroff , DSIR stands for \"Data Selection with Importance Resampling\" (see paper [here](https://arxiv.org/pdf/2302.03169.pdf)) and is used to compute importance weights for each sample with respect to different target domains.\r\n\r\nThe screenshot you posted is from the `prep_artifacts.py` scripts. The flag `--dsir_num_samples` corresponds to the number of samples you use from the target domai", "login": "mauriceweber"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/99#issuecomment-1893300405", "excerpt": "> Hi @BBetteroff , DSIR stands for \"Data Selection with Importance Resampling\" (see paper [here](https://arxiv.org/pdf/2302.03169.pdf)) and is used to compute importance weights for each sample with respect to different target domains.\r\n> \r\n> The screenshot you posted is from the `prep_artifacts.py` scripts. The flag `--dsir_num_samples` corresponds to the number of samples you use from the target", "login": "BBetteroff"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/99#issuecomment-1899929591", "excerpt": "what‘s the content of listing file?,can you show me a example? and what''s the use?", "login": "BBetteroff"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/99#issuecomment-1903430732", "excerpt": "The listing files contain the ids of inputs which, when concatenated with the base uri point to the location of the data. For example:\r\n```\r\n2023-06/0000/de_head.json.gz\r\n2023-06/0000/de_middle.json.gz\r\n2023-06/0000/de_tail.json.gz\r\n2023-06/0000/en_head.json.gz\r\n2023-06/0000/en_middle.json.gz\r\n2023-06/0000/en_tail.json.gz\r\n2023-06/0000/es_head.json.gz\r\n```\r\nFor example, if your data is stored loca", "login": "mauriceweber"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/togethercomputer/RedPajama-Data/issues/99"], "checked_at": "2026-10-09T04:54:42.247369Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_044_iclr_2026_proceedings_credibility@5b8574e4b5059838', 'ca-3e020a72473c5923', 'f-signal-repo-d4c01d613411-97', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-d4c01d613411-97", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-d4c01d613411-97", "repository_id": "repo-d4c01d613411", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/97", "source_title": "possibly missing shard from host", "source_excerpt": "possibly missing shard from host\nI cannot get a valid shard from\r\nhttps://data.together.xyz/redpajama-data-v2/v1.0.0/documents/2014-52/1940/es_middle.json.gz\r\n\r\ncan anyone else replicate this, or is the issue on my end?", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:54:42.248056Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/97#issuecomment-1885236556", "excerpt": "Hi @sagnak , thanks for flagging that -- there are indeed a few files in the dataset which are broken (a few hundred in total, mostly resulting from failed S3 queries). You can safely skip these.\r\n\r\nSee also the discussion on Huggingface: https://huggingface.co/datasets/togethercomputer/RedPajama-Data-V2/discussions/20\r\n\r\n \r\n", "login": "mauriceweber"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/97#issuecomment-1888160772", "excerpt": "Thanks for the huggingface pointer! Indeed all those aforementioned shards are also broken for me", "login": "sagnak"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/togethercomputer/RedPajama-Data/issues/97"], "checked_at": "2026-10-09T04:54:42.248056Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_044_iclr_2026_proceedings_credibility@5b8574e4b5059838', 'ca-3e020a72473c5923', 'f-signal-repo-d4c01d613411-80', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-d4c01d613411-80", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-d4c01d613411-80", "repository_id": "repo-d4c01d613411", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/80#issuecomment-1791279518", "source_title": "Executing V2 issues", "source_excerpt": "There is no data that needs to be pulled from an external S3 bucket, only your own where you have the ccnet output stored -- it is also only required to create the artifacts. Are you creating your own artifacts for a custom dataset or are you trying to reproduce the quality signals we have provided?\r\n\r\nYou can download the ccnet out from the public urls (https://data.together.xyz/redpajama-data-v2", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:54:42.254473Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/80#issuecomment-1789545586", "excerpt": "I can verify that len(inputs_by_snapsh) is 0\r\n\r\nedit: I seem to not have the listings correct, or the s3 bucket info correct. is it possible to get an example of a listsings.txt and \r\n\r\n\r\nS3_ENDPOINT_URL=\"https://red-pajama.s3.us-east-1.amazonaws.com\"\r\nS3_BUCKET=\"red-pajama\"\r\nS3_CCNET_PREFIX=\"/rs_cc_net\"\r\nS3_PROFILE=\"default\"\r\n\r\nDOCKER_S3_ENDPOINT_URL=\"https://red-pajama.s3.us-east-1.amazonaws.com", "login": "hicotton02"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/80#issuecomment-1790790904", "excerpt": "Hi @hicotton02 , thanks for your question!\r\n\r\n> default.conf is missing lines for the AWS Secret and ID\r\nWe deliberately left these out since so that users specify these via `export AWS_SECRET...` (reduces the risk of uploading access keys to github).\r\n\r\nOnce the environment variables are specified, you can get the listings via\r\n\r\n```bash\r\ns5cmd --profile \"$S3_PROFILE\" --endpoint-url \"$S3_ENDPOINT", "login": "mauriceweber"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/80#issuecomment-1790971924", "excerpt": "Thank you so much for the response. \r\n\r\nIs the s5cmd command supposed to point to my own s3 bucket or someone else''s?\r\n\r\nI created a bucket but it is blank at this time. I remember in V1 we were downloading info from I think Arxiv''s bucket.\r\n\r\nedit: As part of this workstream, do we download ccnet data separately (I see their repo went archive)?", "login": "hicotton02"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/80#issuecomment-1791279518", "excerpt": "There is no data that needs to be pulled from an external S3 bucket, only your own where you have the ccnet output stored -- it is also only required to create the artifacts. Are you creating your own artifacts for a custom dataset or are you trying to reproduce the quality signals we have provided?\r\n\r\nYou can download the ccnet out from the public urls (https://data.together.xyz/redpajama-data-v2", "login": "mauriceweber"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/80#issuecomment-1791329250", "excerpt": "> There is no data that needs to be pulled from an external S3 bucket, only your own where you have the ccnet output stored -- it is also only required to create the artifacts. Are you creating your own artifacts for a custom dataset or are you trying to reproduce the quality signals we have provided?\r\n> \r\n> You can download the ccnet out from the public urls (https://data.together.xyz/redpajama-d", "login": "hicotton02"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/80#issuecomment-1791849769", "excerpt": "Wrote a python script to download all the ccnet data based on your links above. it does this in parallel and is basic. saturated my connection and server to get the most efficient process going.\r\n\r\n```\r\nimport os\r\nimport subprocess\r\nimport multiprocessing as mp\r\n\r\nCC_SNAPSHOT_IDS = [\r\n  \"2014-15\",\r\n  \"2014-23\",\r\n  \"2014-35\",\r\n  \"2014-41\",\r\n  \"2014-42\",\r\n  \"2014-49\",\r\n  \"2014-52\",\r\n  \"2015-14\",\r\n  ", "login": "hicotton02"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/togethercomputer/RedPajama-Data/issues/80#issuecomment-1791279518"], "checked_at": "2026-10-09T04:54:42.254473Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_044_iclr_2026_proceedings_credibility@5b8574e4b5059838', 'ca-3e020a72473c5923', 'f-signal-repo-d4c01d613411-67', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-d4c01d613411-67", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-d4c01d613411-67", "repository_id": "repo-d4c01d613411", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/67#issuecomment-1662089029", "source_title": "Failed building wheel for cc-net", "source_excerpt": "Hi @hicotton02 ,\r\n\r\nI couldn''t reproduce your error on Ubuntu 22.04 with python 3.10 -- Can you confirm that you are running the following steps?\r\n\r\n```bash\r\ncd `cc_net`\r\nmkdir data\r\n\r\nsudo apt-get update\r\nsudo apt install build-essential cmake libboost-system-dev libboost-thread-dev libboost-program-options-dev libboost-test-dev libeigen3-dev zlib1g-dev libbz2-dev liblzma-dev\r\nmake install\r\nmake ", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:54:42.258851Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/67#issuecomment-1662089029", "excerpt": "Hi @hicotton02 ,\r\n\r\nI couldn''t reproduce your error on Ubuntu 22.04 with python 3.10 -- Can you confirm that you are running the following steps?\r\n\r\n```bash\r\ncd `cc_net`\r\nmkdir data\r\n\r\nsudo apt-get update\r\nsudo apt install build-essential cmake libboost-system-dev libboost-thread-dev libboost-program-options-dev libboost-test-dev libeigen3-dev zlib1g-dev libbz2-dev liblzma-dev\r\nmake install\r\nmake ", "login": "mauriceweber"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/67#issuecomment-1663048745", "excerpt": "understood. I actually did a `pip install cc-net` and got it to work, although the python parameter `-l en` was invalid. I also cloned and ran on a WSL2 environment and it worked fine. currently I am working through getting all the data down :)", "login": "hicotton02"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/togethercomputer/RedPajama-Data/issues/67#issuecomment-1662089029"], "checked_at": "2026-10-09T04:54:42.258851Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_044_iclr_2026_proceedings_credibility@5b8574e4b5059838', 'ca-3e020a72473c5923', 'f-signal-repo-d4c01d613411-63', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-d4c01d613411-63", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-d4c01d613411-63", "repository_id": "repo-d4c01d613411", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/63#issuecomment-1619660553", "source_title": "How do i prepare the data for Visualisation?", "source_excerpt": "I think you can follow the steps described in the viz Readme https://github.com/togethercomputer/RedPajama-Data/tree/main/viz#reproducing-the-data-processing-pipeline to expand to the full github or also other slices of the dataset?", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:54:42.259769Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/63#issuecomment-1619660553", "excerpt": "I think you can follow the steps described in the viz Readme https://github.com/togethercomputer/RedPajama-Data/tree/main/viz#reproducing-the-data-processing-pipeline to expand to the full github or also other slices of the dataset?", "login": "mauriceweber"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/63#issuecomment-1635956800", "excerpt": "I have tried following the steps. It''s creating the pca32.faisis file. But as per the main.py file, it''s loading the data from \"https://huggingface.co/datasets/meerkat-ml/lemma/resolve/main/filtered_08cdfa755e6d4d89b673d5bd1acee5f6.mk.tar.gz\". How do I create that data which can be passed?", "login": "dittops"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/togethercomputer/RedPajama-Data/issues/63#issuecomment-1619660553"], "checked_at": "2026-10-09T04:54:42.259769Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_044_iclr_2026_proceedings_credibility@5b8574e4b5059838', 'ca-3e020a72473c5923', 'f-signal-repo-d4c01d613411-48', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-d4c01d613411-48", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-d4c01d613411-48", "repository_id": "repo-d4c01d613411", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/48#issuecomment-1584834499", "source_title": "Overlap between Common Crawl and C4", "source_excerpt": "Hi @codesoap ! Thanks for your question. You''re right, the quoted passage comes from the LLama paper -- when building the RP dataset, our goal was to replicate the training data used in LLama, so we tried our best to follow the recipe as closely as possible.\r\n\r\nRegarding the overlap between C4 and the CC slice in RP: C4 is based on the April 2019 CC dump (checkout pp. 5-7 in https://arxiv.org/pdf/", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:54:42.262887Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/48#issuecomment-1563925404", "excerpt": "from paper:\r\nC4 [15%]. During exploratory experiments, we\r\nobserved that using diverse pre-processed Com-\r\nmonCrawl datasets improves performance. We thus\r\nincluded the publicly available C4 dataset (Raffel\r\net al., 2020) in our data. The preprocessing of C4\r\nalso contains deduplication and language identifi-\r\ncation steps: the main difference with CCNet is\r\nthe quality filtering, which mostly rel", "login": "vince62s"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/48#issuecomment-1565292719", "excerpt": "Thanks for the input. The passage you quoted seems to stem from the [LLaMa whitepaper](https://arxiv.org/pdf/2302.13971v1.pdf). This seems like something that could have been a coincidence. Can we be sure, that RedPajama is similar enough to the LLaMa dataset, that the same findings can be applied here? Has anyone compared the perplexity of two networks trained with and without the C4 data?", "login": "codesoap"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/48#issuecomment-1584834499", "excerpt": "Hi @codesoap ! Thanks for your question. You''re right, the quoted passage comes from the LLama paper -- when building the RP dataset, our goal was to replicate the training data used in LLama, so we tried our best to follow the recipe as closely as possible.\r\n\r\nRegarding the overlap between C4 and the CC slice in RP: C4 is based on the April 2019 CC dump (checkout pp. 5-7 in https://arxiv.org/pdf/", "login": "mauriceweber"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/48#issuecomment-1584997306", "excerpt": "Hi @mauriceweber, thanks for chiming in! I''m afraid I still have trouble understanding how the common crawl dataset works. By looking at the [common crawl stats page you''ve linked](https://commoncrawl.github.io/cc-crawl-statistics/plots/crawloverlap) and assuming that the dates in the first graph there are in the format year-week ([I think this is what this code confirms](https://github.com/common", "login": "codesoap"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/48#issuecomment-1594273336", "excerpt": "I think CC is using a new seed of urls in every crawl that they run -- so the seed results in some sense in a random collection of urls visited, which is why there is generally only limited overlap (also between neighbouring crawls).\r\n\r\nMy best guess about the observation that sim(crawl_i, crawl_{i+1}) ~ 0 but sim(crawl_i, crawl_{i+2}) ~ 0.15 is that they perform relatively strict deduplication of", "login": "mauriceweber"}, {"source_url": "https://github.com/togethercomputer/RedPajama-Data/issues/48#issuecomment-1595677778", "excerpt": "Thanks a ton, @mauriceweber! I couldn''t find this information on commoncrawl.org or [the Wikipedia article](https://en.wikipedia.org/wiki/Common_Crawl), but the first slide of the PDF you linked mentions it: \"sample crawls, not a comprehensive crawl\". Now I finally understand.\r\n\r\nIf I read https://commoncrawl.github.io/cc-crawl-statistics/plots/crawlsize correctly, then commoncrawl currently knows", "login": "codesoap"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/togethercomputer/RedPajama-Data/issues/48#issuecomment-1584834499"], "checked_at": "2026-10-09T04:54:42.262887Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
