INSERT INTO credibility_r2.credibility_claims (case_id, credibility_claim_id, paper_version_id, payload) VALUES ('paper_049_iclr_2025_proceedings_credibility@d5c17c16810f1773', 'paper_049_iclr_2025_proceedings_credibility_claim_001', 'paper_049_iclr_2025_proceedings', '{"credibility_claim_id": "paper_049_iclr_2025_proceedings_credibility_claim_001", "paper_version_id": "paper_049_iclr_2025_proceedings", "source_chunk_id": "paper_049_iclr_2025_proceedings_chunk_0001", "claim_text": "However, existing methods typically rely on a supervised learning paradigm, leading to (1) expensive training cost due to repeated invocations of traditional solvers to generate training labels, and (2) plausible yet infeasible solutions due to the misalignment between the training objective (minimizing prediction loss) and the inference objective (generating high-quality solutions).", "claim_type": "other", "importance": "major", "verifiability": true, "dedup_group_id": null, "page_number": 1, "extraction_source": "existing_ai_semantic_descriptor_alignment", "review_status": "reviewed", "exclusion_reason": null}'::jsonb) ON CONFLICT (case_id, credibility_claim_id) DO NOTHING;
