INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_050_iclr_2025_proceedings_credibility@776dcfeb3ac8ccc3', 'signal-repo-4fa7295fba68-5591', 'repo-4fa7295fba68', 'discussion_inconclusive', '{"signal_id": "signal-repo-4fa7295fba68-5591", "repository_id": "repo-4fa7295fba68", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/google/flax/issues/5591", "source_title": "NNX MultiHeadAttention: is_causal=True during decode attends only to key position 0", "source_excerpt": "NNX MultiHeadAttention: is_causal=True during decode attends only to key position 0\n## `is_causal=True` during NNX decode attends only to key position 0\r\n\r\n`nnx.MultiHeadAttention` documents `is_causal` as the way to overlay a causal mask, and decode already installs a cache-occupancy mask (`arange(max_length) <= cur_index`) so a single query can attend to every written KV slot.\r\n\r\nThose two flags", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:56:49.814277Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/google/flax/issues/5591#issuecomment-5751878627", "excerpt": "I opened a fix in https://github.com/google/flax/pull/5592 decode now skips the extra is_causal tril so it keeps the cache occupancy mask only.", "login": "Anu27n"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_050_iclr_2025_proceedings_credibility@776dcfeb3ac8ccc3', 'signal-repo-4fa7295fba68-5589', 'repo-4fa7295fba68', 'discussion_inconclusive', '{"signal_id": "signal-repo-4fa7295fba68-5589", "repository_id": "repo-4fa7295fba68", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/google/flax/issues/5589", "source_title": "`NNXMeta.add_axis` / `remove_axis` are no-ops, silently dropping axis metadata under Linen `scan` / `vmap`", "source_excerpt": "`NNXMeta.add_axis` / `remove_axis` are no-ops, silently dropping axis metadata under Linen `scan` / `vmap`\n# Description\n\n## System information\n\n- **OS Platform and Distribution:** Windows 11 (code read; repro not executed locally: see note under Steps to reproduce)\n- **Flax, jax, jaxlib versions:** Flax at main commit `4f42ed06` (version `0.12.9` per `flax/version.py`); local env had JAX/jaxlib `", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:56:49.814328Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": []}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_050_iclr_2025_proceedings_credibility@776dcfeb3ac8ccc3', 'signal-repo-4fa7295fba68-5571', 'repo-4fa7295fba68', 'discussion_inconclusive', '{"signal_id": "signal-repo-4fa7295fba68-5571", "repository_id": "repo-4fa7295fba68", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/google/flax/issues/5571", "source_title": "nnx.capture fails with nnx.scan when the model contains nnx.List (mixed str/int pytree dict keys)", "source_excerpt": "nnx.capture fails with nnx.scan when the model contains nnx.List (mixed str/int pytree dict keys)\n### System information\n\n- Flax 0.12.7, JAX 0.10.1, Python 3.14, macOS arm64 (CPU)\n\n### Problem\n\n`nnx.capture` fails when the wrapped function runs an `nnx.scan` and the model contains an `nnx.List` (directly or via `nnx.Sequential`):\n\n```\nValueError: Comparator raised exception while sorting pytree di", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:56:50.732653Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/google/flax/issues/5571#issuecomment-5683238604", "excerpt": "Thanks for noticing this, @maxencefaldor. The mechanism used by `nnx.capture` will change in the near future, which would eliminate this issue (see #5556 ), but in the meantime, I think the easiest way to get around this is to make the `__capture__` key used by `nnx.capture` into something that is comparable with ints.", "login": "samanklesaria"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
INSERT INTO credibility_r2.reproduction_signals (case_id, signal_id, repository_id, signal_type, payload) VALUES ('paper_050_iclr_2025_proceedings_credibility@776dcfeb3ac8ccc3', 'signal-repo-4fa7295fba68-5512', 'repo-4fa7295fba68', 'discussion_inconclusive', '{"signal_id": "signal-repo-4fa7295fba68-5512", "repository_id": "repo-4fa7295fba68", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/google/flax/issues/5512#issuecomment-4776162858", "source_title": "flax.nnx.cond causes tracing cache misses", "source_excerpt": "I''ve been looking into this and reproduced the cache misses on current main (flax 0.12.7 / jax 0.10.1) with the provided script. The cause is as described: on the graph_updates=False path, nnx.cond builds a fresh SimpleCondFn wrapper for each branch on every call, and since jax.lax.cond keys its tracing cache on callable identity (and SimpleCondFn is a `@dataclass(eq=False)`, so identity-based), e", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:56:51.551237Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/google/flax/issues/5512#issuecomment-4776162858", "excerpt": "I''ve been looking into this and reproduced the cache misses on current main (flax 0.12.7 / jax 0.10.1) with the provided script. The cause is as described: on the graph_updates=False path, nnx.cond builds a fresh SimpleCondFn wrapper for each branch on every call, and since jax.lax.cond keys its tracing cache on callable identity (and SimpleCondFn is a `@dataclass(eq=False)`, so identity-based), e", "login": "chenkuanliao"}, {"source_url": "https://github.com/google/flax/issues/5512#issuecomment-4896979049", "excerpt": "Currently reviewing @chenkuanliao''s PR, as they were the first to respond to this issue. ", "login": "samanklesaria"}, {"source_url": "https://github.com/google/flax/issues/5512#issuecomment-4897501232", "excerpt": "@samanklesaria thanks for the review and comments. I have updated the PR according to your suggestions. ", "login": "chenkuanliao"}]}'::jsonb) ON CONFLICT (case_id, signal_id) DO NOTHING;
