INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_050_iclr_2025_proceedings_credibility@776dcfeb3ac8ccc3', 'ca-5a6c607e598ff9fc', 'f-signal-repo-4fa7295fba68-5591', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-4fa7295fba68-5591", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-4fa7295fba68-5591", "repository_id": "repo-4fa7295fba68", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/google/flax/issues/5591", "source_title": "NNX MultiHeadAttention: is_causal=True during decode attends only to key position 0", "source_excerpt": "NNX MultiHeadAttention: is_causal=True during decode attends only to key position 0\n## `is_causal=True` during NNX decode attends only to key position 0\r\n\r\n`nnx.MultiHeadAttention` documents `is_causal` as the way to overlay a causal mask, and decode already installs a cache-occupancy mask (`arange(max_length) <= cur_index`) so a single query can attend to every written KV slot.\r\n\r\nThose two flags", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:56:49.814277Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/google/flax/issues/5591#issuecomment-5751878627", "excerpt": "I opened a fix in https://github.com/google/flax/pull/5592 decode now skips the extra is_causal tril so it keeps the cache occupancy mask only.", "login": "Anu27n"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/google/flax/issues/5591"], "checked_at": "2026-10-09T04:56:49.814277Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
