INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_050_iclr_2025_proceedings_credibility@776dcfeb3ac8ccc3', 'ca-5a6c607e598ff9fc', 'f-signal-repo-4fa7295fba68-5571', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-4fa7295fba68-5571", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-4fa7295fba68-5571", "repository_id": "repo-4fa7295fba68", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/google/flax/issues/5571", "source_title": "nnx.capture fails with nnx.scan when the model contains nnx.List (mixed str/int pytree dict keys)", "source_excerpt": "nnx.capture fails with nnx.scan when the model contains nnx.List (mixed str/int pytree dict keys)\n### System information\n\n- Flax 0.12.7, JAX 0.10.1, Python 3.14, macOS arm64 (CPU)\n\n### Problem\n\n`nnx.capture` fails when the wrapped function runs an `nnx.scan` and the model contains an `nnx.List` (directly or via `nnx.Sequential`):\n\n```\nValueError: Comparator raised exception while sorting pytree di", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "open", "resolution_url": null, "observed_at": "2026-10-09T04:56:50.732653Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/google/flax/issues/5571#issuecomment-5683238604", "excerpt": "Thanks for noticing this, @maxencefaldor. The mechanism used by `nnx.capture` will change in the near future, which would eliminate this issue (see #5556 ), but in the meantime, I think the easiest way to get around this is to make the `__capture__` key used by `nnx.capture` into something that is comparable with ints.", "login": "samanklesaria"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/google/flax/issues/5571"], "checked_at": "2026-10-09T04:56:50.732653Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
INSERT INTO credibility_r2.credibility_findings (case_id, credibility_assessment_id, finding_id, dimension_id, severity, payload) VALUES ('paper_050_iclr_2025_proceedings_credibility@776dcfeb3ac8ccc3', 'ca-5a6c607e598ff9fc', 'f-signal-repo-4fa7295fba68-5512', 'code_reproduction_signals', 'info', '{"finding_id": "f-signal-repo-4fa7295fba68-5512", "dimension_id": "code_reproduction_signals", "severity": "info", "status": "pending_verification", "title": "discussion_inconclusive", "description": "关键词检索候选，需人工确认是否讨论论文结果。", "reproduction_signal": {"signal_id": "signal-repo-4fa7295fba68-5512", "repository_id": "repo-4fa7295fba68", "signal_type": "discussion_inconclusive", "review_status": "candidate", "source_url": "https://github.com/google/flax/issues/5512#issuecomment-4776162858", "source_title": "flax.nnx.cond causes tracing cache misses", "source_excerpt": "I''ve been looking into this and reproduced the cache misses on current main (flax 0.12.7 / jax 0.10.1) with the provided script. The cause is as described: on the graph_updates=False path, nnx.cond builds a fresh SimpleCondFn wrapper for each branch on every call, and since jax.lax.cond keys its tracing cache on callable identity (and SimpleCondFn is a `@dataclass(eq=False)`, so identity-based), e", "third_party_claim": "关键词检索候选，需人工确认是否讨论论文结果。", "third_party": null, "author_response": null, "resolution_status": "closed", "resolution_url": null, "observed_at": "2026-10-09T04:56:51.551237Z", "confidence": null, "limitations": ["未运行代码；关键词命中不能证明复现成功或失败。", "作者身份仅依据显式提供的 author_logins。"], "comments": [{"source_url": "https://github.com/google/flax/issues/5512#issuecomment-4776162858", "excerpt": "I''ve been looking into this and reproduced the cache misses on current main (flax 0.12.7 / jax 0.10.1) with the provided script. The cause is as described: on the graph_updates=False path, nnx.cond builds a fresh SimpleCondFn wrapper for each branch on every call, and since jax.lax.cond keys its tracing cache on callable identity (and SimpleCondFn is a `@dataclass(eq=False)`, so identity-based), e", "login": "chenkuanliao"}, {"source_url": "https://github.com/google/flax/issues/5512#issuecomment-4896979049", "excerpt": "Currently reviewing @chenkuanliao''s PR, as they were the first to respond to this issue. ", "login": "samanklesaria"}, {"source_url": "https://github.com/google/flax/issues/5512#issuecomment-4897501232", "excerpt": "@samanklesaria thanks for the review and comments. I have updated the PR according to your suggestions. ", "login": "chenkuanliao"}]}, "internal_evidence": [], "external_source_urls": ["https://github.com/google/flax/issues/5512#issuecomment-4776162858"], "checked_at": "2026-10-09T04:56:51.551237Z", "uncertainty": "第三方公开线索；系统没有运行代码。关闭 issue 不等于结果已复现。"}'::jsonb) ON CONFLICT (case_id, credibility_assessment_id, finding_id) DO NOTHING;
